import { useState } from "react";
import Header from "./components/Header";
import "./App.css";
import { getWeather } from "./services/api";
import sunImage from "./img/image.png";

function App() {
  const [city, setCity] = useState("");
  const [weather, setWeather] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  async function handleSearch(event) {
    event.preventDefault();

    if (!city.trim()) {
      setError("Enter a city name");
      return;
    }

    setLoading(true);
    setError("");

    try {
      const data = await getWeather(city.trim());
      setWeather(data);
    } catch {
      setError("City not found. Try another city.");
      setWeather(null);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="app">
      <Header />

      <main>
        {/* ГЛАВНОЕ ФОТО: src/img/weather.jpg */}
        <section className="hero">
          <h1>Weather dashboard</h1>

          <div className="hero__text">
            <p>
              Create your personal list of favorite cities and always be
              aware of the weather.
            </p>

            <p>October 2023</p>
            <p>Friday, 13ᵗʰ</p>
          </div>

          <form className="hero__search" onSubmit={handleSearch}>
            <input
              type="text"
              placeholder="Search location..."
              value={city}
              onChange={(event) => setCity(event.target.value)}
            />

            <button type="submit" aria-label="Search">
              ⌕
            </button>
          </form>

          {loading && <p>Loading weather...</p>}
          {error && <p>{error}</p>}
        </section>

        {/* ТРИ КАРТОЧКИ ПОГОДЫ */}
        <section className="weather-cards">
          {[1, 2, 3].map((item) => (
            <article className="weather-card" key={item}>
              <div className="weather-card__cities">
                <span>{weather?.name || "Prague"}</span>
                <span>{weather?.sys?.country || "CZ"}</span>
              </div>

              <p className="weather-card__time">
                {weather
                  ? `${new Date(
                      (weather.dt + weather.timezone) * 1000
                    ).toISOString().slice(11, 16)}`
                  : "14:00"}
              </p>

              <p className="weather-card__day">
                {weather
                  ? new Date().toLocaleDateString("en-GB", {
                      day: "2-digit",
                      month: "2-digit",
                      year: "numeric",
                    })
                  : "Today | Friday"}
              </p>

              <div className="weather-card__labels">
                <span>
                  {weather?.weather?.[0]?.description || "Mostly sunny"}
                </span>
              </div>

              {weather?.weather?.[0]?.icon ? (
                <img
                  className="weather-card__sun"
                  src={`https://openweathermap.org/img/wn/${weather.weather[0].icon}@2x.png`}
                  alt={weather.weather[0].description}
                />
              ) : (
                <img
                  className="weather-card__sun"
                  src={sunImage}
                  alt="Sunny weather"
                />
              )}

              <p className="weather-card__temperature">
                {weather ? `${Math.round(weather.main.temp)}°C` : "22°C"}
              </p>

              <div className="weather-card__bottom">
                <span>↻</span>
                <span>♡</span>
                <button type="button">See more</button>
                <span>▣</span>
              </div>
            </article>
          ))}
        </section>

        {/* НИЖНИЙ КОНТЕЙНЕР ПОКА НЕ МЕНЯЕМ */}
        <section className="footer-container">
          <div className="footer-container__content">
            <h2>24/7 Forecast</h2>
            <p>Weather updates for your day</p>
          </div>
        </section>
      </main>
    </div>
  );
}

export default App;
